@startuml

class Bettor {
  + name : string
}

class Race {
  + id : int
  + winner : Runner
}

class Runner {
  + horseName : string
  + jockey : Jockey
}

class Jockey {
  + name : string
}

class Bet {
  + amount : double
  + odds : float
  + race : Race
  + runner : Runner
}

Bettor "1" -- "*" Bet : places
Race "1" -- "*" Bet : has
Runner "0..*" -- "1" Bet : participates
Jockey "0..*" -- "1" Runner : rides

@enduml

